package nl.smartstreamlabs.sbwdroneconfig;
import net.minecraft.client.gui.*;import net.minecraft.client.gui.screens.Screen;import net.minecraft.client.gui.components.Button;import net.minecraft.network.chat.Component;import java.util.*;
/** Replicated state only. Every button is checked again by the server at the actual control panel. */
public final class DefenseScreen extends Screen{
 private final DefenseBlockEntity block;private int x,y,w,h,page,launcherPage,rows,launcherRows;private final Button[]slots=new Button[4],targets=new Button[5],launchers=new Button[4];private final UUID[]targetIds=new UUID[5],launcherIds=new UUID[4];private Button deploy,load,unload,fire,power,automatic,remote,unlink;private int ticks;
 private static Component t(String k,Object...a){return Component.translatable("defense."+k,a);}private static net.minecraft.network.chat.MutableComponent status(String k){return Component.translatable("defense.status."+k);}public DefenseScreen(DefenseBlockEntity b){super(t(b.kind()==0?"pl01.title":"dr01.title"));block=b;}
 private Button button(String key,int x,int y,int width,Runnable action){var b=Button.builder(t(key),v->action.run()).bounds(x,y,width,20).build();addRenderableWidget(b);return b;}private void send(int action,int slot,UUID value){AddonNetwork.defenseAction(new DefenseAction(block.getBlockPos(),action,slot,value==null?new UUID(0,0):value));}
 @Override protected void init(){w=Math.min(480,width-16);h=Math.min(block.kind()==0?330:410,height-16);x=(width-w)/2;y=(height-h)/2;rows=Math.max(1,Math.min(5,(h-(block.kind()==0?194:285))/22));int cw=(w-30)/4;if(block.kind()==0){for(int i=0;i<4;i++){final int s=i;slots[i]=button("slot",x+10+i*(cw+3),y+55,cw,()->send(2,s,null));}load=button("load",x+10,y+80,cw,()->send(3,0,null));unload=button("unload",x+13+cw,y+80,cw,()->send(4,0,null));fire=button("fire",x+16+cw*2,y+80,cw,()->send(6,0,null));button("next_loaded",x+19+cw*3,y+80,cw,()->send(13,0,null));deploy=button("deploy",x+10,y+105,w-20,()->send(1,0,null));}else{deploy=button("deploy",x+10,y+55,cw,()->send(1,0,null));power=button("power",x+13+cw,y+55,cw,()->send(7,0,null));automatic=button("automatic",x+16+cw*2,y+55,cw*2+3,()->send(8,0,null));}
  int top=block.kind()==0?151:100;for(int i=0;i<targets.length;i++){final int s=i;targets[i]=button("target",x+10,y+top+i*22,w-20,()->{if(targetIds[s]!=null)send(5,0,targetIds[s]);});}int pagesY=y+top+rows*22;int pw=(w-35)/4;button("previous",x+10,pagesY,pw,()->page=Math.max(0,page-1));button("next",x+15+pw,pagesY,pw,()->page++);if(block.kind()==1){button("launchers_previous",x+20+pw*2,pagesY,pw,()->launcherPage=Math.max(0,launcherPage-1));button("launchers_next",x+25+pw*3,pagesY,pw,()->launcherPage++);}
  if(block.kind()==1){int begin=pagesY+27;launcherRows=Math.max(1,Math.min(4,(y+h-57-begin)/22));for(int i=0;i<launchers.length;i++){final int s=i;launchers[i]=button("launcher",x+10,begin+i*22,w-20,()->{if(launcherIds[s]!=null)send(10,0,launcherIds[s]);});}remote=button("assign_fire",x+10,y+h-52,(w-25)/2,()->send(11,0,null));unlink=button("unlink",x+15+(w-25)/2,y+h-52,(w-25)/2,()->send(12,0,null));}button("close",x+w-105,y+h-27,95,this::onClose);send(0,0,null);tick();}
 @Override public void tick(){if(minecraft.player==null||block.isRemoved()||minecraft.player.distanceToSqr(net.minecraft.world.phys.Vec3.atCenterOf(block.getBlockPos()))>225){onClose();return;}if(++ticks%40==0)send(9,0,null);deploy.setMessage(t(block.phase==0||block.phase==3?"deploy":"retract"));if(block.kind()==0){for(int i=0;i<4;i++)slots[i].setMessage(Component.literal((i==block.selected?"> ":"")+(i+1)+" ").append(status(block.ammo.get(i).isEmpty()?"EMPTY":"LOADED")));load.active=block.ammo.get(block.selected).isEmpty()&&(block.phase==0||block.phase==2);unload.active=!block.ammo.get(block.selected).isEmpty()&&(block.phase==0||block.phase==2);fire.active=block.phase==2&&!block.status.equals("OPENING_COVER")&&block.target!=null&&block.ammo.stream().anyMatch(s->!s.isEmpty());}else{power.setMessage(t("power_value",status(block.enabled?"ON":"OFF")));automatic.setMessage(t("auto_value",status(block.automatic?"ON":"OFF")));remote.active=block.active()&&block.target!=null&&block.selectedLauncher!=null;}
  page=Math.min(Math.max(0,page),Math.max(0,(block.contacts.size()-1)/rows));for(int i=0;i<targets.length;i++){int at=page*rows+i;targetIds[i]=at<block.contacts.size()?block.contacts.getCompound(at).getUUID("UUID"):null;targets[i].visible=i<rows&&targetIds[i]!=null;if(targetIds[i]!=null){var n=block.contacts.getCompound(at);boolean stale=minecraft.level.getGameTime()-block.scanned>DefenseConfig.SCAN.get()*3;targets[i].setMessage(Component.literal((targetIds[i].equals(block.target)?"> ":"")+font.plainSubstrByWidth(n.getString("Name"),Math.max(30,w-205))+String.format(Locale.ROOT,"  %.0f m  %+.0f m  ",n.getDouble("Distance"),n.getDouble("Height"))).append(status(stale?"STALE":"TRACKING")));}}
  if(block.kind()==1){launcherPage=Math.min(launcherPage,Math.max(0,(block.launchers.size()-1)/launcherRows));for(int i=0;i<launchers.length;i++){int at=launcherPage*launcherRows+i;launcherIds[i]=at<block.launchers.size()?block.launchers.getCompound(at).getUUID("UUID"):null;launchers[i].visible=i<launcherRows&&launcherIds[i]!=null;if(launcherIds[i]!=null){var n=block.launchers.getCompound(at);launchers[i].setMessage(Component.literal((launcherIds[i].equals(block.selectedLauncher)?"> ":"")+n.getString("Name")+" #"+launcherIds[i].toString().substring(0,6)+String.format(java.util.Locale.ROOT," %.0f m  ",n.getDouble("Distance"))).append(status(n.getString("Status"))));}}}}
 @Override public void renderBackground(GuiGraphics g,int mx,int my,float partial){super.renderBackground(g,mx,my,partial);drawPanel(g);}
 private void drawPanel(GuiGraphics g){g.fill(x,y,x+w,y+h,0xf0182324);g.fill(x,y,x+w,y+3,0xff9fae78);g.drawString(font,title,x+10,y+10,0xffe4e8d9);String phase=switch(block.phase){case 1->"DEPLOYING";case 2->"READY";case 3->"RETRACTING";default->"SERVICE";};g.drawString(font,status(phase).append(" / ").append(status(block.status)),x+10,y+26,0xffffd38a);if(block.kind()==0){g.drawString(font,t("radar_value",status(block.radarState).append(block.radarId==null?"":" / DR-01 #"+block.radarId.toString().substring(0,6))),x+10,y+40,0xffc5d2c4);g.drawString(font,t("cooldown_value",Math.max(0,block.nextShot-minecraft.level.getGameTime())/20d),x+10,y+132,0xffc5d2c4);}else g.drawString(font,t("contacts_value",block.contacts.size(),block.launchers.size()),x+10,y+82,0xffc5d2c4);String selected="";for(var v:block.contacts){var n=(net.minecraft.nbt.CompoundTag)v;if(block.target!=null&&n.getUUID("UUID").equals(block.target))selected=n.getString("Name")+String.format(java.util.Locale.ROOT," %.0f m",n.getDouble("Distance"));}g.drawString(font,font.plainSubstrByWidth(t("selected_target",selected.isEmpty()?status("NO_TARGET").getString():selected).getString(),Math.max(40,w-125)),x+10,y+h-20,0xffc5d2c4);}
 @Override public boolean isPauseScreen(){return false;}
}
